mapper.select:
SELECT s.skill_code AS code, s.name, s.description, s.icon_url AS iconUrl, CAST(v.id AS CHAR) AS versionId, v.package_digest AS packageDigest, s.owner_type AS ownerType, s.visibility, COALESCE(NULLIF(UPPER(JSON_UNQUOTE(JSON_EXTRACT( CASE WHEN JSON_VALID(v.definition_json) THEN v.definition_json ELSE '{}' END, '$.outputKind'))), ''), 'TEXT') AS outputKind FROM aid_skill s LEFT JOIN aid_runtime_agent_skill_ref r ON r.agent_version_id = #{agentVersionId} AND r.skill_id = s.id AND r.skill_code = s.skill_code JOIN aid_skill_version v ON v.skill_id = s.id AND v.id = CASE WHEN s.owner_type = 'PLATFORM' AND r.skill_version_id IS NOT NULL THEN r.skill_version_id ELSE s.current_version_id END WHERE s.status = '0' AND s.del_flag = '0' AND v.status = '0' AND v.del_flag = '0' AND v.executor_type = 'PROMPT' AND v.publish_status IN ('PUBLISHED', 'PRIVATE') AND ((#{scope} = 'OFFICIAL' AND s.owner_type = 'PLATFORM' AND s.visibility = 'PUBLIC' AND v.visibility = 'PUBLIC' AND ((s.invocation_scope IN ('INTERNAL', 'ENTRYPOINT') AND v.invocation_scope = s.invocation_scope AND v.package_digest = r.package_digest) OR (s.invocation_scope = 'ENTRYPOINT' AND v.invocation_scope = 'ENTRYPOINT' AND v.publish_status = 'PUBLISHED' AND s.executor_type = 'PROMPT' AND JSON_UNQUOTE(JSON_EXTRACT( CASE WHEN JSON_VALID(v.definition_json) THEN v.definition_json ELSE '{}' END, '$.outputKind')) = 'IMAGE' AND EXISTS (SELECT 1 FROM aid_runtime_agent_tool_ref t WHERE t.agent_version_id = #{agentVersionId} AND t.tool_code = 'canvas.media.generate_skill_image'))))
OR ((#{scope} = 'OWNED' OR #{code} IS NOT NULL OR #{scope} = 'OFFICIAL') AND s.owner_type = 'USER' AND s.owner_user_id = #{userId} AND s.visibility IN ('PRIVATE', 'PUBLIC') AND v.visibility IN ('PRIVATE', 'PUBLIC') AND s.invocation_scope = 'ENTRYPOINT' AND v.invocation_scope = 'ENTRYPOINT')
) AND s.skill_code = #{code}
AND s.skill_code IN #{selectedCode}
AND (s.name LIKE CONCAT('%', #{keyword}, '%') ESCAPE '=' OR s.description LIKE CONCAT('%', #{keyword}, '%') ESCAPE '=' OR s.skill_code LIKE CONCAT('%', #{keyword}, '%') ESCAPE '=')
ORDER BY s.skill_code, s.id LIMIT #{offset}, #{limit}
